/* ---------- base ---------- */
*,*::before,*::after{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0;
  font-family:var(--font-sans);
  font-size:14px;
  line-height:1.5;
  color:var(--ink);
  background:var(--paper);
  -webkit-font-smoothing:antialiased;
  -moz-osx-font-smoothing:grayscale;
  overflow:hidden;
}
button{font:inherit;color:inherit;background:none;border:0;padding:0;cursor:pointer}
a{color:inherit;text-decoration:none}
ul,ol,dl,dd{margin:0;padding:0;list-style:none}
h1,h2,h3,h4,p{margin:0}
svg{display:block}
:focus-visible{outline:2px solid var(--prussian);outline-offset:2px;border-radius:3px}
::selection{background:var(--amber-soft);color:var(--ink)}

*{scrollbar-width:thin;scrollbar-color:var(--line) transparent}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{
  background:var(--line);
  border:3px solid transparent;
  background-clip:content-box;
  border-radius:99px;
}
::-webkit-scrollbar-thumb:hover{background-color:var(--ink-3)}

.ic{
  width:18px;height:18px;flex:none;
  fill:none;stroke:currentColor;stroke-width:1.6;
  stroke-linecap:round;stroke-linejoin:round;
}
.mono{font-family:var(--font-mono);font-variant-numeric:tabular-nums}
.sr-only{
  position:absolute;width:1px;height:1px;padding:0;margin:-1px;
  overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0;
}

/* ---------- app shell ---------- */
.app{
  display:grid;
  grid-template-columns:var(--sidebar-w) minmax(0,1fr) var(--trace-w);
  height:100dvh;
  min-height:0;
  transition:grid-template-columns .22s ease;
}
.app.trace-collapsed{grid-template-columns:var(--sidebar-w) minmax(0,1fr) 0px}
.app.trace-collapsed .trace{opacity:0;pointer-events:none;overflow:hidden}
.app.sidebar-collapsed{grid-template-columns:var(--sidebar-rail) minmax(0,1fr) var(--trace-w)}
.app.sidebar-collapsed.trace-collapsed{grid-template-columns:var(--sidebar-rail) minmax(0,1fr) 0px}

/* ============================================================
   SIDEBAR — single column, DSH-style
   ============================================================ */
.sidebar{
  position:relative;
  display:flex;flex-direction:column;min-height:0;
  padding:6px 8px;
  background:var(--paper-2);
  border-right:1px solid var(--line);
  z-index:20;
  overflow:hidden;
}
.sb-top{
  flex:none;
  display:flex;align-items:center;justify-content:space-between;
  gap:6px;height:44px;padding:0 2px 0 6px;
}
.sb-brand{
  display:flex;align-items:center;gap:8px;min-width:0;
  color:var(--ink);
  font-size:14px;font-weight:650;letter-spacing:-.01em;
  white-space:nowrap;
}
.sb-brand-mark{
  width:22px;height:22px;flex:none;
  fill:none;stroke:currentColor;stroke-width:1.7;
  stroke-linecap:round;stroke-linejoin:round;
}
.sb-brand-mark .hot{fill:var(--amber);stroke:none}
.sb-toggle{
  display:grid;place-items:center;flex:none;
  width:28px;height:28px;border-radius:5px;
  color:var(--ink-3);
  transition:color .15s,background .15s;
}
.sb-toggle:hover{color:var(--ink);background:var(--surface-2)}
.sb-toggle .ic{width:16px;height:16px}

.sb-new{
  display:flex;align-items:center;gap:7px;
  height:34px;margin:6px 0 8px;padding:0 10px;
  border:1px solid var(--line);
  border-radius:6px;
  background:var(--surface);
  color:var(--ink);
  font-size:12.5px;font-weight:550;
  box-shadow:var(--shadow-sm);
  white-space:nowrap;
  transition:border-color .15s,background .15s;
}
.sb-new:hover{border-color:var(--ink-3)}
.sb-new .ic{width:15px;height:15px;flex:none}

.sb-nav{display:flex;flex-direction:column;gap:1px;flex:none}
.sb-nav-item{
  display:flex;align-items:center;gap:9px;
  height:31px;padding:0 9px;
  border-radius:5px;
  color:var(--ink-2);
  font-size:12.5px;white-space:nowrap;
  transition:background .12s,color .12s;
}
.sb-nav-item .ic{width:16px;height:16px;flex:none;color:var(--ink-3)}
.sb-nav-item:hover{background:rgba(20,27,32,.045);color:var(--ink)}
html[data-theme="dark"] .sb-nav-item:hover{background:rgba(255,255,255,.05)}
.sb-nav-item.is-active{background:var(--surface);color:var(--ink);font-weight:600;box-shadow:var(--shadow-sm)}
.sb-nav-item.is-active .ic{color:var(--prussian)}

.sb-sessions{
  flex:1;min-height:0;
  display:flex;flex-direction:column;
  margin-top:10px;padding-top:10px;
  border-top:1px solid var(--line);
}
.sb-sessions-head{
  display:flex;align-items:center;justify-content:space-between;
  padding:0 8px 6px;
}
.sb-sessions-head h2{font-size:11px;font-weight:600;color:var(--ink-3);letter-spacing:.03em}
.sb-sessions-head .mono{font-size:9.5px;color:var(--ink-3)}

.search{position:relative;display:block;margin:0 4px 6px}
.search .ic{
  position:absolute;left:9px;top:50%;transform:translateY(-50%);
  width:14px;height:14px;color:var(--ink-3);
}
.search input{
  width:100%;height:32px;padding:0 9px 0 30px;
  border:1px solid transparent;border-radius:6px;
  background:var(--surface-2);color:var(--ink);
  font:inherit;font-size:12px;outline:none;
  transition:border-color .15s,background .15s;
}
.search input::placeholder{color:var(--ink-3)}
.search input:focus{border-color:var(--line);background:var(--surface)}

.session-scroll{flex:1;overflow-y:auto;min-height:0;padding:0 2px 8px}
.session-group{padding-top:6px}
.group-label{padding:0 8px 5px;font-size:10.5px;font-weight:500;color:var(--ink-3);letter-spacing:.03em}
.session{
  display:block;width:100%;text-align:left;
  padding:8px 8px 8px 10px;
  border-radius:6px;
  border-left:2px solid transparent;
  transition:background .12s;
}
.session:hover{background:rgba(20,27,32,.045)}
html[data-theme="dark"] .session:hover{background:rgba(255,255,255,.04)}
.session.is-active{background:var(--surface);border-left-color:var(--ink);box-shadow:var(--shadow-sm)}
.session-title{display:block;font-size:12.5px;font-weight:550;letter-spacing:-.005em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.session.is-active .session-title{font-weight:650}
.session-meta{display:flex;align-items:center;gap:5px;margin-top:3px;font-size:10.5px;color:var(--ink-3)}
.session-meta .dot{width:5px;height:5px}
.session-meta .sep{opacity:.5}

.dot{display:inline-block;flex:none;width:6px;height:6px;border-radius:50%;background:var(--ink-3)}
.dot.is-live{background:var(--amber);box-shadow:0 0 0 3px var(--amber-soft);animation:pulse 2.4s ease-in-out infinite}
.dot.is-ok{background:var(--green)}
.dot.is-warn{background:var(--red)}

.sb-foot{flex:none;margin-top:auto;padding-top:8px;border-top:1px solid var(--line)}
.sb-conn{display:flex;align-items:center;gap:6px;padding:0 8px 6px;font-size:10px;color:var(--ink-3)}
.sb-conn .spacer{flex:1}
.sb-conn .mono{font-size:9.5px;letter-spacing:.02em}
.sb-account{
  display:flex;align-items:center;gap:8px;
  width:100%;padding:6px 7px;border-radius:6px;text-align:left;
  transition:background .12s;
}
.sb-account:hover{background:var(--surface-2)}
.sb-account-text{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px}
.sb-account-name{font-size:12px;font-weight:600;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sb-account-sub{font-size:10px;color:var(--ink-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sb-account-more{width:15px;height:15px;flex:none;color:var(--ink-3)}

.avatar{
  display:grid;place-items:center;flex:none;
  width:30px;height:30px;border-radius:50%;
  background:var(--amber);color:#191307;
  font-family:var(--font-mono);font-size:11px;font-weight:700;letter-spacing:.02em;
}

html[data-theme="dark"] .ic-sun{display:block}
html[data-theme="dark"] .ic-moon{display:none}
.ic-sun{display:none}
.ic-moon{display:block}

/* collapsed rail */
.app.sidebar-collapsed .sidebar{padding:6px 0;align-items:center}
.app.sidebar-collapsed .sb-top{width:100%;height:44px;justify-content:center;padding:0}
.app.sidebar-collapsed .sb-brand{display:none}
.app.sidebar-collapsed .sb-new{
  width:36px;height:36px;margin:6px auto 8px;padding:0;justify-content:center;
  border-color:transparent;background:transparent;box-shadow:none;
}
.app.sidebar-collapsed .sb-new:hover{background:var(--surface-2)}
.app.sidebar-collapsed .sb-new span{display:none}
.app.sidebar-collapsed .sb-nav{width:100%;align-items:center;gap:2px}
.app.sidebar-collapsed .sb-nav-item{width:36px;height:36px;padding:0;justify-content:center;border-radius:7px}
.app.sidebar-collapsed .sb-nav-item span{display:none}
.app.sidebar-collapsed .sb-sessions{display:none}
.app.sidebar-collapsed .sb-foot{width:100%;display:flex;justify-content:center;padding-top:6px}
.app.sidebar-collapsed .sb-conn{display:none}
.app.sidebar-collapsed .sb-account{width:36px;height:36px;padding:0;justify-content:center;margin:0 auto}
.app.sidebar-collapsed .sb-account-text,
.app.sidebar-collapsed .sb-account-more{display:none}

/* account menu */
.account-menu{
  position:absolute;left:8px;right:8px;bottom:74px;z-index:95;
  display:none;padding:6px;
  border:1px solid var(--line);border-radius:8px;
  background:var(--surface);box-shadow:var(--shadow-md);
}
.account-menu.is-open{display:block}
.app.sidebar-collapsed .account-menu{position:fixed;left:64px;right:auto;bottom:12px;width:240px}
.account-menu-head{display:flex;align-items:center;gap:9px;padding:6px 7px 9px}
.account-menu-head .avatar{width:32px;height:32px}
.account-menu-name{font-size:12.5px;font-weight:600;color:var(--ink)}
.account-menu-sub{margin-top:1px;font-size:10.5px;color:var(--ink-3)}
.menu-sep{height:1px;margin:5px 4px;background:var(--line-2)}
.menu-item{
  display:flex;align-items:center;gap:8px;
  width:100%;height:33px;padding:0 7px;
  border-radius:5px;color:var(--ink-2);
  font-size:12.5px;text-align:left;
  transition:background .12s,color .12s;
}
.menu-item:hover{background:var(--surface-2);color:var(--ink)}
.menu-item .ic{width:15px;height:15px;color:var(--ink-3)}
.menu-item.is-danger{color:var(--red)}
.menu-item.is-danger .ic{color:var(--red)}
.menu-version{padding:7px 7px 3px;font-family:var(--font-mono);font-size:9px;color:var(--ink-3);letter-spacing:.03em}

/* responsive sidebar pieces */
.mobile-sidebar-btn{
  display:none;place-items:center;flex:none;
  width:30px;height:30px;margin-right:8px;
  border:1px solid var(--line);border-radius:5px;
  background:var(--surface);color:var(--ink-2);
}
.mobile-sidebar-btn .ic{width:16px;height:16px}
.sidebar-scrim{display:none}

/* ============================================================
   CHAT COLUMN
   ============================================================ */
.chat{
  display:flex;flex-direction:column;
  min-width:0;min-height:0;
  background:var(--paper);
  position:relative;
}
.chat-head{
  flex:none;
  display:flex;align-items:center;justify-content:space-between;gap:20px;
  min-height:68px;
  padding:0 32px;
  border-bottom:1px solid var(--line);
  background:var(--paper);
}
.chat-heading{flex:1;min-width:0}
.chat-title{
  font-size:17px;font-weight:650;letter-spacing:-.012em;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
}
.chat-sub{
  display:flex;align-items:center;gap:8px;
  margin-top:3px;
  font-size:11.5px;color:var(--ink-3);
  white-space:nowrap;overflow:hidden;
}
.chat-sub .mono{font-size:10.5px;color:var(--ink-3)}
.chat-sub .sep{opacity:.45}
.chat-actions{display:flex;align-items:center;gap:8px;flex:none}

.status-chip{
  display:inline-flex;align-items:center;gap:6px;
  height:26px;padding:0 9px;
  border:1px solid var(--line);
  border-radius:5px;
  background:var(--surface);
  color:var(--ink-2);

