import { apiClient } from './client'
import type { ChatMessage, Conversation, ConversationDetail, PageResult } from '@/types'

export interface ConversationListParams { q?: string; status?: string; limit?: number; cursor?: string }
export interface MessageListParams { limit?: number; cursor?: string; before?: string }

export const conversationsApi = {
  async list(params: ConversationListParams = {}): Promise<PageResult<Conversation>> { ... },
  async create(title = '新会话'): Promise<Conversation> { post('/conversations', {title}) },
  async get(id): Promise<ConversationDetail>,
  async update(id, body: {title?: string; status?: 'active'|'archived'}): Promise<Conversation>,
