```

`src/stores/conversations.ts`：
```ts
export const useConversationsStore = defineStore('conversations', () => {
  const items = ref<Conversation[]>([])
  const stats = ref<Record<string, number>>({})
  const loading = ref(false)
  const q = ref('')
  const status = ref<'all'|'active'|'archived'>('all')
  const hasMore = ref(false)
  const nextCursor = ref<string|null>(null)
  const error = ref<string|null>(null)

  const grouped = computed(() => { ... today/yesterday/earlier })
  const pendingCount = computed(...)

  async function load(reset = true) {
    if (loading.value) return
    loading.value = true
    error.value = null
    try {
      const page = await conversationsApi.list({ q: q.value || undefined, status: status.value, limit: 30, cursor: reset ? undefined : nextCursor.value ?? undefined })
      items.value = reset ? page.items : [...items.value, ...page.items]
      stats.value = page.stats ?? {}
      hasMore.value = page.has_more
      nextCursor.value = page.next_cursor
    } catch (e) { error.value = ... } finally { loading.value = false }
  }

  async function search(next: string) { q.value = next; await load(true) }
  async function setStatus(next) { status.value = next; await load(true) }
  async function create(): Promise<Conversation> { const conv = await conversationsApi.create(); items.value.unshift(conv); return conv }
  async function rename(id, title) { const updated = await conversationsApi.update(id, {title}); replace(updated) }
  async function archive(id) { const updated = await conversationsApi.update(id, {status:'archived'}); replace(updated) }
  async function remove(id) { await conversationsApi.delete(id); items.value = items.value.filter(...) }
  function touch(id, patch: Partial<Conversation>) { ... }
  function replace(conversation) { ... }
  return {...}
})
```

分组 computed：
```ts
interface Group { label: string; items: Conversation[] }
const grouped = computed<Group[]>(() => {
  const today: Conversation[] = []; const yesterday = []; const earlier = []
  const now = new Date(); const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime()
  const startOfYesterday = startOfToday - 86400000
  for (const c of items.value) {
    const ts = c.last_message_at ? Date.parse(c.last_message_at) : Date.parse(c.created_at)
    if (ts >= startOfToday) today.push(c)
    else if (ts >= startOfYesterday) yesterday.push(c)
    else earlier.push(c)
  }
  return [ {label:'今天', items:today}, ... ].filter(g => g.items.length)
})
```
