`formatRelative` 实现用 dayjs（已安装）：
```ts
import dayjs from 'dayjs'
import relativeTime from 'dayjs/plugin/relativeTime'
import 'dayjs/locale/zh-cn'
dayjs.extend(relativeTime)
dayjs.locale('zh-cn')

export function formatRelative(iso: string | null | undefined): string {
  if (!iso) return ''
  const date = dayjs(iso)
  const now = dayjs()
  if (date.isSame(now, 'day')) return date.format('HH:mm')
  if (date.isSame(now.subtract(1, 'day'), 'day')) return '昨天'
  if (date.isAfter(now.subtract(7, 'day'))) return date.format('dddd')
  return date.format('MM-DD')
}
```
dayjs 的 `isSame` 需要 dayjs 对象。OK。

`formatDateTime(iso)` = `YYYY-MM-DD HH:mm`。
`formatTime(iso)` = `HH:mm:ss`。
`formatDuration(ms)` = `<1000 ? ${ms}ms : ${(ms/1000).toFixed(1)}s`；null → '—'。
`formatTokens(n)` = `n >= 1000 ? (n/1000).toFixed(1)+'k' : String(n)`。
`formatBytes(n)` = KB/MB。

