{"content": "<script setup lang="ts">
import { computed } from 'vue'

import { formatRelative } from '@/utils/format'
import type { Conversation } from '@/types'

const props = defineProps<{
  conversation: Conversation
  active: boolean
}>()

const emit = defineEmits<{
  select: [id: string]
  menu: [id: string, action: 'rename' | 'archive' | 'remove']
}>()

const meta = computed(() => {
  const parts: string[] = []
  if (props.conversation.pending_approval_count > 0) {
    parts.push('待审批')
  }
  const time = formatRelative(props.conversation.last_message_at)
  if (time) parts.push(time)
  parts.push(`${props.conversation.message_count} 条消息`)
  return parts
})

const isArchived = computed(() => props.conversation.status === 'archived')
</script>

<template>
  <div class="session-wrap">
    <button
      class="session"
      :class="{ 'is-active': active, 'is-archived': isArchived }"
      type="button"
      :aria-current="active ? 'page' : undefined"
      @click="emit('select', conversation.id)"
    >
      <span class="session-title">{{ conversation.title }}</span>
      <span class="session-meta">
        <span v-if="conversation.pending_approval_count > 0" class="dot is-live"></span>
        <span v-else-if="isArchived" class="dot"></span>
        <template v-for="(part, index) in meta" :key="part">
          <span v-if="index > 0" class="sep">·</span>
          <span>{{ part }}</span>
        </template>
      </span>
    </button>

    <button
      class="session-more"
      type="button"
      aria-label="会话操作"
      title="会话操作"
      @click.stop="emit('menu', conversation.id, 'rename')"
    >
      <svg viewBox="0 0 24 24" aria-hidden="true">
        <circle cx="5" cy="12" r="1.3" fill="currentColor" stroke="none" />
        <circle cx="12" cy="12" r="1.3" fill="currentColor" stroke="none" />
        <circle cx="19" cy="12" r="1.3" fill="currentColor" stroke="none" />
      </svg>
    </button>
  </div>
</template>

<style scoped>
.session-wrap {
  position: relative;
}

.session {
  display: block;
  width: 100%;
  padding: 8px 8px 8px 10px;
  border-left: 2px solid transparent;
