import { fetchEventSource } from '@microsoft/fetch-event-source'
import { apiClient, resolveBaseUrl } from './client'
import { isMockEnabled } from './mock'
import type { ChatEventName, ChatStreamRequest, StreamHandlers } from '@/types'

function isChatEvent(name: string): name is ChatEventName { ... list }

export async function openChatStream(payload, handlers): Promise<void> {
  if (isMockEnabled()) {
    const { mockChatStream } = await import('@/api/mock/stream')
    await mockChatStream(payload, handlers)
    return
  }
  await fetchEventSource(`${resolveBaseUrl()}/chat/stream`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Accept: 'text/event-stream', Authorization: `Bearer ${localStorage...}` },
    body: JSON.stringify(payload),
    signal: handlers.signal,
    openWhenHidden: true,
    async onopen(response) {
      if (!response.ok || !response.headers.get('content-type')?.includes('text/event-stream')) {
        throw new Error(`SSE 连接失败：HTTP ${response.status}`)
      }
      handlers.onOpen?.(response.headers.get('X-Run-ID'))
    },
    onmessage(ev) {
      if (!ev.event || ev.event === 'ping' || !isChatEvent(ev.event)) return
      let data: unknown = {}
      try { data = ev.data ? JSON.parse(ev.data) : {} } catch { console.warn(...); return }
      handlers.onEvent(ev.event, data)
    },
    onerror(error) { handlers.onError(error instanceof Error ? error : new Error(String(error))); throw error },
  })
}
```
注意 `fetchEventSource` 的 `onmessage` 中 `ev.event` 类型 string。`isChatEvent` 用 Set。

使用 `storage.getAccessToken()` 而不是 localStorage 直接读。

但 `import { isMockEnabled } from './mock'` 会静态引入 mock/index（只有 isMockEnabled，很小），动态 import stream。生产构建时 if(false) 分支可能被移除，静态 isMockEnabled 保留。OK。

