export const useChatStore = defineStore('chat', () => {
  const state = ref<ChatState>(createInitialChatState())
  const sending = ref(false)
  let controller: AbortController | null = null
  let deltaBuffer = new Map<string, string>()
  let rafId: number | null = null

  function apply(event, data) { state.value = reduceChat(state.value, event, data) }
  function flushDeltas() { ... apply each buffered delta ... }
  function onEvent(event, data) {
    if (event === 'message.delta') { buffer; schedule raf; return }
    flushDeltas(); apply(event, data)
  }
  async function send(text, context) { ... }
  async function stop() { controller?.abort(); ... }
  async function loadConversation(id) { ... }
  async function resolveApproval(approve) { ... }
  function reset() { if (rafId) cancelAnimationFrame; state.value = createInitialChatState() }
})
```

`send`：
```ts
async function send(text: string, context: ChatContextSelection = {}) {
  const trimmed = text.trim()
  if (!trimmed || state.value.streaming) return
  const clientMessageId = crypto.randomUUID()
  const conversationId = state.value.conversationId ?? undefined
  // 乐观消息
  state.value = { ...state.value, streaming: true, error: null, finishReason: null,
    messages: [...state.value.messages, optimisticUser(trimmed, clientMessageId)],
    currentAssistantId: null, pendingApprovalId: null, usage: null, process: [] }
  controller = new AbortController()
  try {
    await openChatStream({ conversation_id: conversationId, message: trimmed, client_message_id: clientMessageId, ...context }, { signal: controller.signal, onEvent, onError })
  } catch (error) {
    if (isAbort) return
    state.value = { ...state.value, streaming: false, error: { code:'stream_failed', message: error.message } }
  } finally {
    flushDeltas()
    controller = null
  }
}
```
注意：`openChatStream` 的 promise 在流正常结束后 resolve。mock 的 `mockChatStream` 在 message.done 后返回。fetchEventSource 在流关闭后 resolve。

`stop`：
