async function stop() {
  const runId = state.value.runId
  controller?.abort()
  controller = null
  state.value = { ...state.value, streaming: false, finishReason: 'canceled', messages: state.value.messages.map(m => m.streaming ? {...m, streaming:false, status:'canceled'} : m) }
  if (runId) { try { await runsApi.cancel(runId) } catch {} }
}
```

`resolveApproval`：
```ts
async function resolveApproval(approve: boolean) {
  const approvalId = state.value.pendingApprovalId
  if (!approvalId) return
  await approvalsApi.decide(approvalId, { decision: approve ? 'approve':'reject' })
  state.value = markApprovalResolved(state.value, approvalId, approve ? 'approve':'reject')
  state.value = { ...state.value, pendingApprovalId: null }
}
```
markApprovalResolved 更新 process 中 approval decision + status。

