async function loadConversation(id: string) {
  reset()
  state.value = { ...state.value, conversationId: id }
  const page = await conversationsApi.messages(id, { limit: 50 })
  state.value = { ...state.value, messages: page.items.map(toView) }
  const conversation = await conversationsApi.get(id)
  state.value = { ...state.value, conversationTitle: conversation.title }
