async function send(text: string, context: ChatContextSelection = {}) {
  const trimmed = text.trim()
  if (!trimmed || state.value.streaming) return
  const clientMessageId = crypto.randomUUID()
  const conversationId = state.value.conversationId ?? undefined
  // 乐观消息
  state.value = { ...state.value, streaming: true, error: null, finishReason: null,
    messages: [...state.value.messages, optimisticUser(trimmed, clientMessageId)],
    currentAssistantId: null, pendingApprovalId: null, usage: null, process: [] }
  controller = new AbortController()
