    case 'a2a.artifact': {
      const taskId = str(data.task_id)
      if (!taskId) return next
      const artifact = asRecord(data.artifact)
      const existing = next.process.find(
        (item): item is A2aProcess => item.kind === 'a2a' && item.taskId === taskId,
