        id: `approval:${approvalId}`,
        status: 'waiting',
        startedAt: str(data.ts),
        approvalId,
        tool: str(data.tool),
        toolDisplayName: str(data.tool_display_name) || str(data.tool),
        source: str(data.source),
        executor: str(data.executor),
