  color: var(--surface);
}

.btn.primary:hover:not(:disabled) {
  filter: brightness(1.06);
}

.btn:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}

.resolved {
  margin: 10px 0 0;
  color: var(--ink-3);
  font-size: 11px;
}
</style>
