}

.chevron.is-open {
  transform: rotate(180deg);
}

.thinking-body {
  padding: 0 11px 9px;
  color: var(--ink-3);
  font-size: 11.5px;
  line-height: 1.7;
  white-space: pre-wrap;
}
</style>
