      ></textarea>

      <div class="composer-footer">
        <span class="hint">Enter 发送 · Shift+Enter 换行 · @ 文件（后续接入）</span>
        <span class="count mono">{{ count }} / {{ maxChars }}</span>

        <button
          v-if="streaming"
