          class="send is-stop"
          aria-label="停止生成"
          title="停止生成"
          @click="onStop"
        >
          <svg viewBox="0 0 24 24" aria-hidden="true">
            <rect x="7" y="7" width="10" height="10" rx="1.5" />
          </svg>
        </button>
        <button
          v-else
          type="button"
          class="send"
          aria-label="发送"
          title="发送"
          :disabled="!canSend"
          @click="submit"
        >
          <svg viewBox="0 0 24 24" aria-hidden="true">
            <path d="M12 19V5M6 11l6-6 6 6" />
          </svg>
        </button>
      </div>
    </div>
  </footer>
</template>

