```vue
<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'

import ChatComposer from '@/components/chat/ChatComposer.vue'
import ConversationSidebar from '@/components/chat/ConversationSidebar.vue'
import MessageList from '@/components/chat/MessageList.vue'
import RunTraceDrawer from '@/components/chat/RunTraceDrawer.vue'
import { useChatStore } from '@/stores/chat'
import { useConversationsStore } from '@/stores/conversations'
import { useSystemStore } from '@/stores/system'
import type { ChatContextSelection, ReasoningEffortId } from '@/types'

const route = useRoute()
const router = useRouter()
const chat = useChatStore()
const conversations = useConversationsStore()
const system = useSystemStore()

const traceOpen = ref(false)
const model = ref('')
const reasoningEffort = ref<ReasoningEffortId>('low')

const activeId = computed(() => (typeof route.query.c === 'string' ? route.query.c : undefined))
const activeConversation = computed(() => conversations.items.find(item => item.id === activeId.value) ?? null)
const title = computed(() => chat.state.conversationTitle || activeConversation.value?.title || '新对话')
const isEmpty = computed(() => !activeId.value && chat.state.messages.length === 0)
const status = computed(() => {
  if (chat.state.pendingApprovalId) return { label: '待审批', tone: 'warn' }
  if (chat.state.streaming) return { label: '生成中', tone: 'live' }
  if (chat.state.error) return { label: '出错', tone: 'error' }
  return { label: '就绪', tone: 'ok' }
})
const subtitle = computed(() => {
  const modelName = system.models.find?.(...) // models 是数组
  const parts: string[] = []
  if (model.value) parts.push(model.value)
  parts.push(`${chat.state.messages.length} 条消息`)
  return parts.join(' · ')
})

const suggestions = [
  '整理本周客服工单，生成一份团队周报',
  '查一下退款政策变更会影响哪些话术',
  '把这段 release notes 翻成英文',
]

onMounted(async () => {
  void conversations.load()
  void system.load()
  if (activeId.value) await loadConversation(activeId.value)
  model.value = system.defaultModel
  reasoningEffort.value = system.defaultReasoningEffort
})

watch(() => system.defaultModel, (value) => { if (!model.value) model.value = value })
watch(() => system.defaultReasoningEffort, (value) => { reasoningEffort.value = value })

async function loadConversation(id: string) {
  try { await chat.loadConversation(id) } catch (error) { ElMessage.error(error instanceof Error ? error.message : '加载会话失败') }
}

watch(() => route.query.c, (value) => {
  if (typeof value !== 'string') {
    if (!chat.state.streaming) chat.reset()
    return
  }
  if (value === chat.state.conversationId) return
  if (chat.state.streaming) return
  void loadConversation(value)
})

watch(() => chat.state.conversationId, (id) => {
  if (!id || id === activeId.value) return
  void router.replace({ query: { ...route.query, c: id } })
})

watch(() => chat.state.streaming, (streaming, previous) => {
  if (previous && !streaming) {
    void conversations.load()
  }
})

function selectConversation(id: string) {
  void router.replace({ query: { ...route.query, c: id } })
}

function handleRemoved(id: string) {
  if (id !== activeId.value) return
  chat.reset()
  void router.replace({ query: {} })
}

function handleSend(payload: { text: string; context: ChatContextSelection }) {
  void chat.send(payload.text, payload.context).then(() => {
    // 流结束后会话列表刷新由 watch 处理
  })
}

function useSuggestion(text: string) {
  void chat.send(text)
}

async function handleApproval(approve: boolean) {
  try { await chat.resolveApproval(approve) } catch (error) { ElMessage.error(error instanceof Error ? error.message : '审批失败') }
}
</script>
```
注意 `watch(() => route.query.c)` 在 onMounted 之前就注册；初始路由已有 c，watch 不会立即触发（无 immediate）。onMounted 加载。当 query 变化触发。OK。

但当发送新会话时 conversationId 设置为新 id，watch 更新 query；query watch 看到 value === chat.state.conversationId 跳过。好。

当删除当前会话后 `router.replace({query:{}})`，query watch value undefined → `chat.reset()`。chat.reset 已调用，重复无妨。

当切换会话时 chat.loadConversation 会 abort 当前流（如果 streaming，watch 跳过；但用户点侧栏时 select 会改 query，watch 发现 streaming 为 true 直接 return，query 变了但内容没变，UI 会显示新 activeId 但消息还是旧的。问题）。处理：如果在流式时选择另一会话，应该先停止/或禁止。简单：selectConversation 时如果 streaming，先 `chat.stop()` 再切换。但 stop 会调 cancel API。可接受。修改：
```ts
function selectConversation(id: string) {
  if (chat.state.streaming) chat.stop()
  void router.replace(...)
}
```
但 watch 中 `if (chat.state.streaming) return` 在 select 调用 stop 后 streaming 立即 false（stop 同步改 state），然后 router.replace 触发 watch，加载。好。

删除当前会话时若流式中，也 stop。

