/* 通用页面控件 */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--surface);
  color: var(--ink-2);
  font-size: 12px;
  font-weight: 550;
  white-space: nowrap;
  transition:
    border-color 0.15s,
    color 0.15s,
    filter 0.15s;
}

.btn:hover:not(:disabled) {
  border-color: var(--ink-3);
  color: var(--ink);
}

.btn.primary {
  border-color: var(--prussian);
  background: var(--prussian);
  color: var(--surface);
}

.btn.primary:hover:not(:disabled) {
  filter: brightness(1.06);
}

.btn:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.input {
  height: 32px;
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 6px;
  outline: none;
  background: var(--surface);
  color: var(--ink);
  font: inherit;
  font-size: 12px;
}

.input::placeholder {
  color: var(--ink-3);
}

.input:focus {
  border-color: var(--ink-3);
}

.toolbar {
  display: flex;
