      <StatCard label="失败" :value="stats.failed ?? 0" tone="error" />
    </div>

    <div class="toolbar">
      <select v-model="stateFilter" class="input" aria-label="按状态筛选" @change="load">
        <option v-for="option in STATE_OPTIONS" :key="option.value" :value="option.value">
          {{ option.label }}
        </option>
      </select>
